import{_ as l,a0 as u,w as p,s as i,ao as a,I as r,x as e,a1 as n,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"Kubernetes 即将支持机密计算 | LCTT x X-CMD","titleTemplate":false,"description":"Kubernetes 即将支持机密计算 | LCTT (202209) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Kubernetes 即将支持机密计算 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Kubernetes 即将支持机密计算 | LCTT (202209) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202209/20220923 Kubernetes To Soon Support Confidential Computing","title":"Kubernetes 即将支持机密计算","tag":"202209","desc":""},"relativePath":"202209/20220923 Kubernetes To Soon Support Confidential Computing.md","filePath":"[post].md"}'),d={name:"202209/20220923 Kubernetes To Soon Support Confidential Computing.md"};function m(b,t,C,f,T,S){const o=u("Link");return p(),i("div",null,[t[15]||(t[15]=a('<h1 id="kubernetes-即将支持机密计算" tabindex="-1">Kubernetes 即将支持机密计算 <a class="header-anchor" href="#kubernetes-即将支持机密计算" aria-label="Permalink to “Kubernetes 即将支持机密计算”">​</a></h1><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/09/kubernets-on-prem-diy-considerations-1.png" alt=""></p><blockquote><p>Constellation 是第一个始终加密的 kubernetes（K8S）。在这个 K8S 中，你的所有工作负载和控制平面都被完全屏蔽起来，你可以使用加密证书远程确认这一点。</p></blockquote><p>Constellation Kubernetes 引擎使用 <ruby>秘密计算<rt>secret computing</rt></ruby> 和 <ruby>机密虚拟机<rt>confidential VM</rt></ruby>，将 Kubernetes 集群与云架构的其余部分隔离开来。因此，无论是在静态还是在内存中，数据总是被加密的，并创建了一个 <ruby>机密上下文<rt>confidential context</rt></ruby>。根据创建 Constellation 的公司 Edgeless Systems 的说法，由于它为在公共云上运行的数据和工作流增加了安全性和保密性，因此机密计算是云计算的未来。</p><p>Kubernetes 节点在使用 Constellation 的私有虚拟机中运行。根据 Edgeless Systems 的说法，机密虚拟机是安全飞地的演变，它将机密计算的三个原则——运行时加密、隔离和远程证明——扩展到整个虚拟系统。机密虚拟机（TDX）使用底层硬件对私有计算的特殊支持，例如 AMD 安全加密虚拟化（AEM）、SEV-安全嵌套分页（SEV-SNP）和英特尔信任域扩展。此外，ARM 去年还发布了名为 Realms 的新 V9 架构。此设计包括私有 VM 功能。</p><p>Constellation 尝试在集群级别提供证明或通过加密证书进行验证，以及“始终在线”加密。 Constellation 中的机密 VMS 使用了 Fedora CoreOS，它构建在一个不可变的文件系统之上，是面向容器而设计的。Constellation 还利用 Sigstore 来保护 DevOps 信任链。</p><p>使用秘密计算时，性能可能会令人担忧。是的，加密会影响性能，但 AMD 和微软的联合基准测试发现，这只会导致 2% 到 8% 之间的微小性能损失。Edgeless Systems 声称 Constellation 将在繁重的工作负载下表现类似。</p><p>鉴于 Constellation 已通过 CNCF 认证，并且可与包括 GCP 和 Azure 在内的所有主要云服务互操作，这应保证其与其他 Kubernetes 工作负载和工具的互操作性。</p><hr>',9)),r("p",null,[t[1]||(t[1]=e("via: ",-1)),n(o,{href:"https://www.opensourceforu.com/2022/09/kubernetes-to-soon-support-confidential-computing/"},{default:s(()=>[...t[0]||(t[0]=[e("https://www.opensourceforu.com/2022/09/kubernetes-to-soon-support-confidential-computing/",-1)])]),_:1})]),r("p",null,[t[6]||(t[6]=e("作者：",-1)),n(o,{href:"https://www.opensourceforu.com/author/laveesh-kocher/"},{default:s(()=>[...t[2]||(t[2]=[e("Laveesh Kocher",-1)])]),_:1}),t[7]||(t[7]=e(" 选题：",-1)),n(o,{href:"https://github.com/lkxed"},{default:s(()=>[...t[3]||(t[3]=[e("lkxed",-1)])]),_:1}),t[8]||(t[8]=e(" 译者：",-1)),n(o,{href:"https://github.com/littlebirdnest"},{default:s(()=>[...t[4]||(t[4]=[e("littlebirdnest",-1)])]),_:1}),t[9]||(t[9]=e(" 校对：",-1)),n(o,{href:"https://github.com/wxy"},{default:s(()=>[...t[5]||(t[5]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[12]||(t[12]=e("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[10]||(t[10]=[e("LCTT",-1)])]),_:1}),t[13]||(t[13]=e(" 原创编译，",-1)),n(o,{href:"https://linux.cn/"},{default:s(()=>[...t[11]||(t[11]=[e("Linux中国",-1)])]),_:1}),t[14]||(t[14]=e(" 荣誉推出",-1))])])}const x=l(d,[["render",m]]);export{w as __pageData,x as default};
